	self.activityDojo =  ActivityCakeUtils.GetActivityCakeMgr():GetActivityDojo()
	local data = self.activityDojo:GetMainLineData()
	local index = 1
	for i = 1, #self.nodeEnv do
		local isPassNode = ActivityCakeUtils.GetActivityCakeMgr():IsPassChapterNode(data[i].questId)
		if not isPassNode then
			local isUnLock = (checkNumber(data[i].unlockCountdown) - os.time()) <= 0 and ActivityCakeUtils.GetActivityCakeMgr():IsUnLockFirstChapter(data[i].questId)
			if isUnLock then
				index = i
			end
		else
			index = i
		end
		
		if data and not isNull(data[i]) then
			self.nodeEnv[i]:RefreshChapterNodeShow(data[i],i)
		end
	end
	
	self.nodeEnv[index]:RefreshCurrent(true)
